// Cross-check: JS port and the wasm32 build against vectors/renderer.json (generated by the Rust native build).
// Usage: node renderer/js/check.mjs [--js] [--wasm]   (default: both)
import { readFileSync, existsSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { N, render, simulate, imageHash, trailHash, sinTableHash } from './render.mjs';

const root = new URL('../../', import.meta.url);
const vec = JSON.parse(readFileSync(new URL('vectors/renderer.json', root), 'utf8'));
const want = process.argv.slice(2).filter((a) => a.startsWith('--'));
const doJs = want.length === 0 || want.includes('--js'), doWasm = want.length === 0 || want.includes('--wasm');
const spore = (c) => ({ seed: Uint8Array.from(Buffer.from(c.seed, 'hex')), age: c.age, edges: c.edges });
let bad = 0;
const cmp = (what, got, exp) => { if (got !== exp) { bad++; console.log(`  MISMATCH ${what}\n    got ${got}\n    exp ${exp}`); } };

if (doJs) {
  console.log('js port');
  cmp('sin_table_hash', sinTableHash(), vec.sin_table_hash);
  for (const c of vec.cases) {
    const t0 = Date.now(), sp = spore(c);
    cmp(`${c.name} trail`, trailHash(simulate(sp)), c.trail_hash);
    cmp(`${c.name} image`, imageHash(render(sp)), c.image_hash);
    console.log(`  ${c.name.padEnd(20)} ${Date.now() - t0} ms`);
  }
}

if (doWasm) {
  const path = new URL('target/wasm32-unknown-unknown/release/spores_renderer.wasm', root);
  if (!existsSync(path)) { console.log('wasm: build first: cargo build --release -p spores-renderer --target wasm32-unknown-unknown'); process.exit(2); }
  const { instance } = await WebAssembly.instantiate(readFileSync(path), {});
  const x = instance.exports, mem = () => new Uint8Array(x.memory.buffer);
  console.log('wasm32 build (run in node)');
  for (const c of vec.cases) {
    const t0 = Date.now(), sp = spore(c);
    const inp = Buffer.alloc(40 + 12 * sp.edges.length);
    Buffer.from(sp.seed).copy(inp, 0); inp.writeUInt32LE(sp.age, 32); inp.writeUInt32LE(sp.edges.length, 36);
    [...sp.edges].sort((a, b) => a[0] - b[0]).forEach(([id, d], i) => { inp.writeUInt32LE(id, 40 + 12 * i); inp.writeBigUInt64LE(BigInt(d), 44 + 12 * i); });
    const pin = x.alloc(inp.length), pout = x.alloc(x.image_len()), phash = x.alloc(32);
    mem().set(inp, pin);
    if (x.render_into(pin, inp.length, pout) !== 0) { bad++; console.log(`  ${c.name}: render_into failed`); continue; }
    const rgb = mem().slice(pout, pout + x.image_len());
    x.hash_image(pout, phash);
    const wasmHash = Buffer.from(mem().slice(phash, phash + 32)).toString('hex');
    cmp(`${c.name} image (wasm render, JS-side hash)`, imageHash(rgb), c.image_hash);
    cmp(`${c.name} image (wasm render, wasm hash)`, wasmHash, c.image_hash);
    console.log(`  ${c.name.padEnd(20)} ${Date.now() - t0} ms`);
  }
}
console.log(bad === 0 ? 'OK: all hashes match the Rust native vectors' : `FAILED: ${bad} mismatches`);
process.exit(bad === 0 ? 0 : 1);
